size(200,135);

pair A,B,C,D,E,F;
A=(20,0);
B=(20,30);
C=(180,0);
D=(180,30);
E=(85,125);
F=(115,125);

dot(A);
dot(B);
dot(C);
dot(D);
dot(E);
dot(F);

draw(A--C,red);
draw(A--D,red);
draw(B--C,red);
draw(B--D,red);
draw(A--E,blue);
draw(A--F,blue);
draw(B--E,blue);
draw(B--F,blue);
draw(C--E,green);
draw(C--F,green);
draw(D--E,green);
draw(D--F,green);

label("Team 1",(0,15));
label("Team 2",(200,15));
label("Team 3",(100,135));

[/asy]

